const{chromium}=require(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');const fs=require('node:fs');(async()=>{const b=await chromium.launch({executablePath:process.env.MX_CHROME||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});const p=await b.newPage({viewport:{width:1100,height:1100}});const results=[];for(const skin of ['style1','style2']){await p.goto((process.env.MX_AUDIT_URL||'http://127.0.0.1:5183')+'/tests/fixtures/layout-audit.html?'+new URLSearchParams({skin,scene:'insurance-single',width:440,height:782}));await p.locator('#audit-stage[data-ready=true]').waitFor({timeout:60000});const before=await p.locator('.mx-insurance-option[aria-pressed=true]').getAttribute('data-pool');await p.locator('.mx-insurance-option[aria-pressed=false]:not(:disabled)').first().click();const chosen=p.locator('.mx-insurance-option[aria-pressed=true]');const after=await chosen.getAttribute('data-pool');results.push({skin,before,after,count:await chosen.count(),details:await p.locator('.mx-insurance-details').innerText(),pass:before!==after&&await chosen.count()===1});await p.locator('#audit-stage').screenshot({path:`docs/styles/style2/implementation/round1/screens/insurance-selection-${skin}.png`});}const equal=results[0].details===results[1].details&&results[0].after===results[1].after;fs.writeFileSync('docs/styles/style2/implementation/round1/insurance-selection.json',JSON.stringify({results,equal},null,2));console.log({results,equal});if(!equal||results.some(r=>!r.pass))process.exitCode=1;await b.close()})();
